-- Esquema PostgreSQL de DentalApi, alineado con InitialPostgresSchema.
-- Ejecutar conectado a una base vacía llamada dental_api.
-- En pgAdmin, CREATE DATABASE se ejecuta en una consulta aparte:
-- CREATE DATABASE dental_api;
-- Para las instalaciones normales de la API se recomienda `dotnet ef database update`;
-- en Development la API aplica automáticamente las migraciones pendientes.

BEGIN;

CREATE TABLE IF NOT EXISTS public."Odontologos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" character varying(100) NOT NULL,
    "Documento" character varying(30) NOT NULL,
    "Especialidad" character varying(100),
    "Telefono" character varying(30),
    "Correo" character varying(150),
    "Activo" boolean NOT NULL
);

CREATE TABLE IF NOT EXISTS public."Pacientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" character varying(100) NOT NULL,
    "Documento" character varying(30) NOT NULL,
    "Telefono" character varying(30) NOT NULL,
    "Correo" character varying(150),
    "Notas" character varying(1000),
    "CreadoEn" timestamp with time zone NOT NULL
);

CREATE TABLE IF NOT EXISTS public."Tratamientos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" character varying(120) NOT NULL,
    "Descripcion" character varying(1000),
    "PrecioBase" numeric(10,2) NOT NULL,
    "DuracionMinutos" integer NOT NULL,
    "Activo" boolean NOT NULL,
    CONSTRAINT "CK_Tratamientos_Duracion" CHECK ("DuracionMinutos" > 0),
    CONSTRAINT "CK_Tratamientos_PrecioBase" CHECK ("PrecioBase" >= 0)
);

CREATE TABLE IF NOT EXISTS public."Citas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PacienteId" integer NOT NULL,
    "OdontologoId" integer NOT NULL,
    "FechaInicio" timestamp with time zone NOT NULL,
    "FechaFin" timestamp with time zone NOT NULL,
    "Estado" character varying(30) NOT NULL,
    "Motivo" character varying(1000),
    "Notas" character varying(1000),
    "CreadoEn" timestamp with time zone NOT NULL,
    CONSTRAINT "CK_Citas_Estado" CHECK ("Estado" IN ('Programada', 'Confirmada', 'EnCurso', 'Completada', 'Cancelada')),
    CONSTRAINT "CK_Citas_Fechas" CHECK ("FechaFin" > "FechaInicio"),
    CONSTRAINT "FK_Citas_Odontologos_OdontologoId"
        FOREIGN KEY ("OdontologoId") REFERENCES public."Odontologos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Citas_Pacientes_PacienteId"
        FOREIGN KEY ("PacienteId") REFERENCES public."Pacientes" ("Id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS public."CitaTratamientos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CitaId" integer NOT NULL,
    "TratamientoId" integer NOT NULL,
    "PiezaDental" character varying(10),
    "PrecioAplicado" numeric(10,2) NOT NULL,
    "Notas" character varying(1000),
    CONSTRAINT "CK_CitaTratamientos_PrecioAplicado" CHECK ("PrecioAplicado" >= 0),
    CONSTRAINT "FK_CitaTratamientos_Citas_CitaId"
        FOREIGN KEY ("CitaId") REFERENCES public."Citas" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CitaTratamientos_Tratamientos_TratamientoId"
        FOREIGN KEY ("TratamientoId") REFERENCES public."Tratamientos" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Odontologos_Documento" ON public."Odontologos" ("Documento");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Pacientes_Documento" ON public."Pacientes" ("Documento");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Tratamientos_Nombre" ON public."Tratamientos" ("Nombre");
CREATE INDEX IF NOT EXISTS "IX_Citas_OdontologoId_FechaInicio" ON public."Citas" ("OdontologoId", "FechaInicio");
CREATE INDEX IF NOT EXISTS "IX_Citas_PacienteId_FechaInicio" ON public."Citas" ("PacienteId", "FechaInicio");
CREATE INDEX IF NOT EXISTS "IX_CitaTratamientos_CitaId" ON public."CitaTratamientos" ("CitaId");
CREATE INDEX IF NOT EXISTS "IX_CitaTratamientos_TratamientoId" ON public."CitaTratamientos" ("TratamientoId");

COMMIT;
